<script setup lang="ts">
import { Head, useForm, router } from '@inertiajs/vue3'
import { ref } from 'vue'
import ConfirmDialog from '../../Components/ConfirmDialog.vue'
const props=defineProps<{quotas:{data:any[];total:number};usage:Record<string,{total_bytes:number|null;error?:boolean}>}>()
const form=useForm({user_id:'',max_total_bytes:0,max_file_bytes:0,period:'lifetime'})
const deleting=ref(false),selectedUser=ref('')
const bytes=(n:number|null)=>n===null?'نامشخص':n>=1073741824?(n/1073741824).toFixed(2)+' GiB':n>=1048576?(n/1048576).toFixed(2)+' MiB':n+' B'
const percent=(user:string,max:number)=>{const n=props.usage[user]?.total_bytes;if(n===null||n===undefined||max<=0)return 0;return Math.min(100,n/max*100)}
const askDelete=(id:string)=>{selectedUser.value=id;deleting.value=true}
const remove=()=>router.delete('/media/quotas/'+encodeURIComponent(selectedUser.value))
</script>
<template><Head title="مدیا و سهمیه‌ها"/><v-container fluid class="pa-6"><h1 class="text-h4 mb-5">مدیا و سهمیه‌ها</h1><v-row><v-col cols="12" md="4"><v-card rounded="xl" class="pa-5"><v-card-title>تعریف سهمیه کاربر</v-card-title><v-card-text><v-form @submit.prevent="form.post('/media/quotas')"><v-text-field v-model="form.user_id" label="شناسه Matrix کاربر"/><v-text-field v-model.number="form.max_total_bytes" type="number" label="حداکثر مصرف کل (bytes)"/><v-text-field v-model.number="form.max_file_bytes" type="number" label="حداکثر اندازه هر فایل (bytes)"/><v-select v-model="form.period" label="دوره محاسبه" :items="[{title:'بدون بازنشانی',value:'lifetime'},{title:'روزانه',value:'day'},{title:'هفتگی',value:'week'},{title:'ماهانه',value:'month'}]"/><v-btn type="submit" color="primary" block :loading="form.processing">ذخیره سهمیه</v-btn></v-form></v-card-text></v-card></v-col><v-col cols="12" md="8"><v-card rounded="xl" class="pa-5"><v-card-title>مصرف و سهمیه کاربران</v-card-title><v-list><v-list-item v-for="q in quotas.data" :key="q.user_id" :title="q.user_id" :subtitle="bytes(props.usage[q.user_id]?.total_bytes??null)+' / '+bytes(q.max_total_bytes)+' · سقف فایل '+bytes(q.max_file_bytes)+' · '+q.period"><template #prepend><v-progress-circular :model-value="percent(q.user_id,q.max_total_bytes)" :size="48" :width="5" color="primary">{{ Math.round(percent(q.user_id,q.max_total_bytes)) }}%</v-progress-circular></template><template #append><v-btn icon="mdi-delete" color="error" variant="text" @click="askDelete(q.user_id)"/></template></v-list-item></v-list><v-alert v-if="!quotas.data.length" type="info" variant="tonal">هنوز سهمیه‌ای تعریف نشده است.</v-alert></v-card></v-col></v-row><ConfirmDialog v-model="deleting" title="حذف سهمیه" message="محدودیت این کاربر از Media Gate حذف می‌شود." danger @confirm="remove"/></v-container></template>
